"use client";

import { useEffect, useRef } from "react";

export default function FacePage() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let faceMesh: any;
    let camera: any;

    async function loadMediaPipe() {
      // Dynamically load MediaPipe FaceMesh & Camera utils
      const mpFaceMesh = await import("https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh");
      const mpCameraUtils = await import("https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils");

      const { FaceMesh } = mpFaceMesh;
      const { Camera } = mpCameraUtils;

      faceMesh = new FaceMesh({
        locateFile: (file: string) =>
          `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${file}`,
      });

      faceMesh.setOptions({
        maxNumFaces: 1,
        refineLandmarks: true,
        minDetectionConfidence: 0.5,
        minTrackingConfidence: 0.5,
      });

      const video = videoRef.current!;
      const canvas = canvasRef.current!;
      const ctx = canvas.getContext("2d")!;

      faceMesh.onResults((results: any) => {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(results.image, 0, 0, canvas.width, canvas.height);

        if (results.multiFaceLandmarks) {
          ctx.fillStyle = "#00eaff";
          for (const landmarks of results.multiFaceLandmarks) {
            for (const p of landmarks) {
              ctx.beginPath();
              ctx.arc(p.x * canvas.width, p.y * canvas.height, 2, 0, 2 * Math.PI);
              ctx.fill();
            }
          }
        }
      });

      camera = new Camera(video, {
        onFrame: async () => {
          await faceMesh.send({ image: video });
        },
        width: 640,
        height: 480,
      });

      camera.start();
    }

    loadMediaPipe();

    return () => {
      if (camera?.stop) camera.stop();
    };
  }, []);

  return (
    <div style={{ textAlign: "center" }}>
      <h1>MediaPipe FaceMesh Stream</h1>
      <video ref={videoRef} style={{ display: "none" }} />
      <canvas
        ref={canvasRef}
        width={640}
        height={480}
        style={{ border: "1px solid #ccc" }}
      />
    </div>
  );
}
